// FUNCTION: BFME2 0x00271108 size=190 name=?handleWeaponFireFX@Drawable@@QAE_NHHHMMMH@Z evidence=N:ledger tier=A
Bool Drawable::handleWeaponFireFX(Int wslot, Int specificBarrelToUse, const FXList *fxl, Real weaponSpeed,
	Real recoilAmount, Real recoilAngle, const Coord3D *victimPos)
{
	if (recoilAmount != 0.0f)
	{
		// The kick is relative to the object's heading and points backwards.
		if (m_object)
			recoilAngle -= m_object->getOrientation();
		recoilAngle += 3.14159265f;
		if (m_locoInfo)
		{
			m_locoInfo->m_accelerationPitchRate += recoilAmount * Cos(recoilAngle);
			m_locoInfo->m_accelerationRollRate += recoilAmount * Sin(recoilAngle);
		}
	}
	for (DrawModule **dm = drawModuleList(); *dm; ++dm)
	{
		ObjectDrawInterface *odi = (*dm)->getObjectDrawInterface();
		if (odi && odi->handleWeaponFireFX(wslot, specificBarrelToUse, fxl, weaponSpeed, victimPos))
			return true;
	}
	return false;
}

