// FUNCTION: BFME2 0x002744F2 size=159 name=?play@TintEnvelope@@QAEXPBURGBColor@@III@Z evidence=N:ledger tier=A
const Real FADE_RATE_EPSILON = 0.001f;

void TintEnvelope::play(const RGBColor *peak, UnsignedInt attackFrames, UnsignedInt decayFrames, UnsignedInt sustainAtPeak)
{
	setPeakColor(peak);

	setAttackFrames(attackFrames);
	setDecayFrames(decayFrames);

	m_envState = ENVELOPE_STATE_ATTACK;
	m_sustainCounter = sustainAtPeak;
	m_affect = TRUE;

	Vector3 delta;
	Vector3::Subtract(m_currentColor, m_peakColor, &delta);

	if (delta.Length() <= FADE_RATE_EPSILON)	// practically at this color already
		m_envState = ENVELOPE_STATE_SUSTAIN;
}

// FUNCTION: BFME2 0x00274591 size=551 name=?update@TintEnvelope@@QAEXXZ evidence=N:ledger tier=A
void TintEnvelope::update()
{
	switch (m_envState)
	{
		case (ENVELOPE_STATE_REST):
		{
			m_currentColor.Set(0, 0, 0);
			m_affect = FALSE;
			break;
		}
		case (ENVELOPE_STATE_DECAY):
		{
			if (m_decayRate.Length() > m_currentColor.Length() || m_currentColor.Length() <= FADE_RATE_EPSILON)
			{
				m_envState = ENVELOPE_STATE_REST;
				m_affect = FALSE;
			}
			else
			{
				Vector3::Add(m_decayRate, m_currentColor, &m_currentColor);
				m_affect = TRUE;
			}
			break;
		}
		case (ENVELOPE_STATE_ATTACK):
		{
			Vector3 delta;
			Vector3::Subtract(m_currentColor, m_peakColor, &delta);

			if (m_attackRate.Length() > delta.Length() || delta.Length() <= FADE_RATE_EPSILON)
			{
				if (m_sustainCounter)
				{
					m_envState = ENVELOPE_STATE_SUSTAIN;
				}
				else
				{
					m_envState = ENVELOPE_STATE_DECAY;
				}
			}
			else
			{
				Vector3::Add(m_attackRate, m_currentColor, &m_currentColor);
				m_affect = TRUE;
			}
			break;
		}
		case (ENVELOPE_STATE_SUSTAIN):
		{
			if (m_sustainCounter > 0)
				--m_sustainCounter;
			else
				release();
			break;
		}
		default:
		{
			break;
		}
	}
}

