void Drawable::clearCustomSoundAmbient(Bool restartSound)
{
	// Stop ambient sound if it's playing
	stopAmbientSound();
	m_customSoundAmbientInfo.clear();
	if (restartSound)
		startAmbientSound(FALSE);
}

