void Drawable::setCustomSoundAmbientInfo(const OpaqueRefElement4 &customAmbientInfo)
{
	clearCustomSoundAmbient(FALSE);
	m_customSoundAmbientInfo = customAmbientInfo;
	startAmbientSound(FALSE);
}

